    totals: Dict[str, float] = {}
    for tx in transactions:
        account = _read_account(tx)
        amount = _read_amount(tx)
        totals[account] = amount
    return {
        account: math.floor(amount * 100.0 + 0.5) / 100.0
        for account, amount in totals.items()
    }

